
const images={draw:'data:image/png;base64,',capture:'data:image/png;base64,',import:'data:image/png;base64,'};
const descriptions={draw:'Draw — a familiar workspace for ideas made on screen.',capture:'Capture — review your photographed artwork before choosing its motion.',import:'Import — choose existing artwork from your photos; the home screen makes this entry point explicit.'};
document.querySelectorAll('.choice').forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.entry;document.querySelectorAll('.choice').forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});document.querySelector('.entry-phone').src=images[key];document.querySelector('.entry-phone').alt=descriptions[key];document.querySelector('.entry-caption').textContent=descriptions[key]}));
document.querySelector('.toggle').addEventListener('click',e=>{const open=document.querySelector('.control-preview').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open));e.currentTarget.textContent=open?'Back to the main screen ↙':'Explore advanced settings ↗'});
const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(n=>observer.observe(n));
const stages=[...document.querySelectorAll('.story-step')],phones=[...document.querySelectorAll('.story-phone')];function update(){let nearest=0,best=Infinity;stages.forEach((n,i)=>{const r=n.getBoundingClientRect(),d=Math.abs(r.top+r.height/2-innerHeight/2);if(d<best){best=d;nearest=i}});phones.forEach((p,i)=>p.classList.toggle('active',i===nearest));const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.progress').style.width=(max?scrollY/max*100:0)+'%'}let pending=false;addEventListener('scroll',()=>{if(!pending){pending=true;requestAnimationFrame(()=>{update();pending=false})}},{passive:true});addEventListener('resize',update);update();
